def transform(grid):
    """Transform input grid into 2x2 quadrant expanded output"""
    n = len(grid)
    output = [[0]*(2*n) for _ in range(2*n)]
    for r in range(n):
        for c in range(n):
            # TL: unchanged
            output[r][c] = grid[r][c]
            # TR: 90° CW
